  "revision_action": "strengthen",
  "supportive_card_ids": ["C73", "C63", "C72", "C28", "C22", "C76", "C78", "C79", "C83", "C85", "C84"],
  "contradictory_card_ids": ["C42", "C07", "C13", "C02", "C16", "C37"],
  "prediction_basis_card_ids": ["C73", "C63", "C72", "C28", "C22", "C76", "C78", "C79", "C83", "C85", "C84"],
  "claims": [
    {
      "claim": "The query is a fully ionized aryloxyacetic acid at intestinal pH (logD -0.75), and L5 shows that a free carboxylic acid (ME3277) had poor absorptive flux unless its acids were esterified (C73), providing mechanistic evidence that the ionized acid form has low intestinal permeability.",
      "card_ids": ["C73"]
    },
    {
      "claim": "Pravastatin, an acidic drug with a similar ionization profile, undergoes BCRP-mediated efflux in Caco-2 cells (C63) and has an estimated fraction absorbed of only 34% in a 2/4/A1 monolayer (C72), indicating that acidic substrates can face gut-wall efflux and incomplete absorption.",
      "card_ids": ["C63", "C72"]
    },
    {
      "claim": "L6 adds hepatic-clearance evidence: pravastatin shows substantial intrinsic clearance in rat hepatocytes (C78), high in vivo hepatic elimination rates (C79, C83, C85), and a perfused-rat-liver clearance of 24.1 mL/min (C76), while lovastatin acid is mainly eliminated by UGT metabolism (C84); this supports first-pass hepatic loss for acidic drugs.",
      "card_ids": ["C76", "C78", "C79", "C83", "C85", "C84"]
    },
    {
      "claim": "Direct low outcomes for related contexts (FK788 in rats 9.6%, C28; KNI-272 fed syrup 15.72%, C22) align with the low prediction, whereas high-F analogs (cicaprost ~100%, C42; FK788 human 55%, C07; etodolac 0.80, C13) are less transferable because of structural and species differences and do not override the coherent permeability/efflux/hepatic-clearance mechanism.",
      "card_ids": ["C28", "C22", "C42", "C07", "C13"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "strengthened",
      "card_ids": ["C76", "C78", "C79", "C83", "C85", "C84"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "No treprostinil-specific hepatic or permeability record is present in the supplied cards; the low prediction relies on analog and mechanistic transfer.",
    "Fed-state effects on this specific molecule are not directly measured; food can increase F for some high-first-pass drugs (C37) but its effect on the query is unknown.",
    "The target species is not specified; human versus rat differences are substantial (e.g., FK788 human 55% vs rat 9.6%, C07 vs C28).",
    "The transporter status (BCRP, OATP, MCT) and metabolic enzyme profile of the query are not directly assayed."
  ],
  "decision_summary": "Prediction remains low and is strengthened by L6 hepatic-clearance evidence: pravastatin shows substantial hepatic intrinsic/perfused-liver clearance (C76, C78, C79, C83, C85) and lovastatin acid undergoes UGT metabolism (C84), adding first-pass loss to the existing poor free-acid permeability/efflux evidence (C73, C63) and direct low analog outcomes (C28, C22). High-F analogs (C42, C07, C13) are less transferable due to structural and species differences."
}

